if(!exists('build_collections_episodes'))library(creditratingsystem)
c_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
c_near<-function(x,y,tol=1e-12)stopifnot(isTRUE(all.equal(x,y,tolerance=tol,check.attributes=FALSE)))
c_case<-function(){dates<-c('2024-01-01','2024-01-10','2024-02-01','2024-02-10','2024-03-20');states<-c('DEFAULT','CLEAN','ARREARS','CLEAN','DEFAULT');list(states=lapply(seq_along(dates),function(i)list(account_id='A',state_event_id=paste0('e',i-1L),state=states[i],occurred_at=dates[i],known_at=dates[i])),actions=list(),coverage=list(list(account_id='A',observed_from='2024-01-01',observed_through='2024-04-30',known_at='2024-04-30')),episode_rule=list(rule_id='synthetic',version='1',problem_states=c('ARREARS','DEFAULT'),clean_states='CLEAN',terminal_states='CLOSED',default_states='DEFAULT',probation_days=10,separation_days=15),evaluation_cutoff='2024-04-30')}
h<-do.call(build_collections_episodes,c_case());ep<-h$value$episodes;stopifnot(identical(vapply(ep,`[[`,character(1),'status'),c('CURED','CURED','OPEN')),ep[[1]]$ended_at=='2024-01-25',ep[[2]]$ended_at=='2024-02-25',is.null(ep[[3]]$ended_at),ep[[2]]$previous_episode_id==ep[[1]]$episode_id,all(vapply(ep,`[[`,logical(1),'ever_default')))
v<-build_cure_targets(h,30,90,'2024-04-30')$value;stopifnot(identical(vapply(v,`[[`,numeric(1),'cure_label'),c(1,1,0)),v[[1]]$cure_at=='2024-01-20',v[[1]]$redefault_at=='2024-03-20',v[[1]]$redefault_label==1)
a<-c_case();a$states<-a$states[1:2];a$coverage<-list();h<-do.call(build_collections_episodes,a);v<-build_cure_targets(h,30,30,a$evaluation_cutoff)$value;stopifnot(h$value$episodes[[1]]$status=='OPEN',is.null(v[[1]]$cure_label),is.null(v[[1]]$redefault_label))
a<-c_case();a$states<-a$states[1:3];a$states[[3]]$occurred_at<-a$states[[3]]$known_at<-'2024-01-20';h<-do.call(build_collections_episodes,a);stopifnot(length(h$value$episodes)==1,build_cure_targets(h,30,30,a$evaluation_cutoff)$value[[1]]$cure_label==0)
a<-c_case();a$states<-a$states[1:2];a$states[[2]]$state<-'CLOSED';h<-do.call(build_collections_episodes,a);v<-build_cure_targets(h,30,30,a$evaluation_cutoff)$value[[1]];stopifnot(h$value$episodes[[1]]$status=='TERMINATED',v$cure_status=='CENSORED_EXIT',is.null(v$cure_label))
# Exit after healed episode is still in complete account history and censors redefault.
a<-c_case();a$states<-a$states[1:3];a$states[[3]]$state<-'CLOSED';h<-do.call(build_collections_episodes,a);v<-build_cure_targets(h,30,90,a$evaluation_cutoff)$value[[1]];stopifnot(h$value$episodes[[1]]$status=='CURED',length(h$value$episodes[[1]]$timeline)==2,length(h$value$state_history)==3,v$cure_label==1,v$redefault_status=='CENSORED_EXIT',is.null(v$redefault_label))
a<-c_case();a$actions<-list(list(action_id='offer',account_id='A',action_type='plan',stage='OFFERED',occurred_at='2024-01-05',known_at='2024-01-06'),list(action_id='late',account_id='A',action_type='plan',stage='PERFORMED',occurred_at='2024-01-07',known_at='2024-05-01'));h<-do.call(build_collections_episodes,a);stopifnot(length(h$value$episodes[[1]]$actions)==1);bad<-h;bad$value$rule$probation_days<-0;c_error('INTEGRITY_ERROR',build_cure_targets(bad,30,30,a$evaluation_cutoff));c_error('COLLECTIONS_CUTOFF',build_cure_targets(h,30,30,'2024-05-01'))
a<-c_case();a$coverage[[1]]$observed_from<-'2023-12-01';c_error('COLLECTIONS_COVERAGE',do.call(build_collections_episodes,a));a<-c_case();a$states[[2]]$occurred_at<-'2024-01-01';c_error('COLLECTIONS_AMBIGUITY',do.call(build_collections_episodes,a))
c_action<-function(){list(actions=list(list(action_id='offer',treatment_id='plan1',account_id='A',action_type='plan',stage='OFFERED',occurred_at='2024-01-10',known_at='2024-01-12')),features=list(list(feature_record_id='income-before',account_id='A',feature='income',value=2000,observed_at='2024-01-01',known_at='2024-01-02'),list(feature_record_id='income-after',account_id='A',feature='income',value=5000,observed_at='2024-01-09',known_at='2024-01-11')),outcomes=list(list(outcome_id='prior',account_id='A',event_type='payment',occurred_at='2024-01-10',known_at='2024-01-11'),list(outcome_id='future',account_id='A',event_type='payment',occurred_at='2024-01-20',known_at='2024-01-20')),coverage=c_case()$coverage,index_stage='OFFERED',required_features='income',horizon_days=30,maximum_feature_age_days=30,evaluation_cutoff='2024-04-30')}
v<-do.call(build_collections_action_history,c_action())$value$rows[[1]];stopifnot(v$preaction_features$income==2000,!v$accepted,!v$performed,identical(v$prior_or_same_day_outcome_ids,list('prior')),v$outcomes[[1]]$outcome_id=='future',v$outcome_complete,!v$causal_effect_identified)
a<-c_action();a$coverage<-list();a$actions[[2]]<-a$actions[[1]];a$actions[[2]]$action_id<-'performed';a$actions[[2]]$stage<-'PERFORMED';a$actions[[2]]$occurred_at<-a$actions[[2]]$known_at<-'2024-01-05';v<-do.call(build_collections_action_history,a)$value$rows[[1]];stopifnot(v$invalid_stage_order,!v$descriptive_eligible,!v$outcome_complete)
a<-c_action();a$maximum_feature_age_days<-8;v<-do.call(build_collections_action_history,a)$value$rows[[1]];stopifnot(identical(v$stale_features,list('income')),!v$descriptive_eligible)
a<-c_action();a$features[[1]]['value']<-list(NULL);v<-do.call(build_collections_action_history,a)$value$rows[[1]];stopifnot(identical(v$missing_features,list('income')),is.null(v$preaction_features$income))
a<-c_action();a$features[[3]]<-a$features[[1]];a$features[[3]]$feature_record_id<-'tied';c_error('COLLECTIONS_AMBIGUITY',do.call(build_collections_action_history,a))
c_arrangement<-function(){base<-list(plan_id='baseline',payments=c(500,500,0),period_interest_rates=c(0,0,0),new_fees=c(0,0,0),servicing_costs=c(0,0,0),receipt_fractions=c(1,1,1),capitalize_unpaid_interest=FALSE);candidate<-base;candidate$plan_id<-'deferral';candidate$payments<-c(0,500,500);list(contract=list(currency='EUR',principal=1000,principal_arrears=200,accrued_interest=0,fees=0,as_of='2024-01-01'),baseline=base,candidate=candidate,affordability_paths=list(list(path_id='income-stress',currency='EUR',available_cash=c(400,400,400))),discount_factors=c(1,.9,.8),period_end_dates=c('2024-02-01','2024-03-01','2024-04-01'),currency='EUR')}
a<-c_arrangement();v<-do.call(simulate_repayment_arrangement,a)$value;stopifnot(v$baseline$npv==950,v$candidate$npv==850,v$npv_change== -100,v$candidate$remaining_claim==0,sum(vapply(v$candidate$schedule,`[[`,numeric(1),'paid_principal'))==1000,identical(unlist(v$candidate$affordability[[1]]$residual_cash),c(400,-100,-100)),!v$contract_changed,!v$default_status_changed)
a$candidate<-a$baseline;stopifnot(do.call(simulate_repayment_arrangement,a)$value$npv_change==0)
a<-c_arrangement();a$candidate$payments<-c(0,1000,1000);a$candidate$period_interest_rates<-c(.1,.1,0);a$candidate$capitalize_unpaid_interest<-TRUE;v<-do.call(simulate_repayment_arrangement,a)$value$candidate$schedule;stopifnot(v[[1]]$capitalized_interest==100,v[[1]]$closing_principal==1100,v[[2]]$interest_accrued==110,v[[2]]$paid_interest==110,v[[2]]$paid_principal==890,v[[2]]$closing_principal==210,v[[3]]$received_payment==210,v[[3]]$unused_payment_capacity==790)
a<-c_arrangement();a$candidate$receipt_fractions<-c(1,0,1);v<-do.call(simulate_repayment_arrangement,a)$value$candidate;stopifnot(v$remaining_claim==500,v$npv==400,identical(unlist(v$affordability[[1]]$residual_cash),c(400,-100,-100)))
c_recovery<-function(){period<-'2024-12-31';scenario<-function(id,recovery,cost)list(scenario_id=id,probability=1,cashflows=list(list(cashflow_id='recovery',kind='RECOVERY',period_end=period,amount=recovery),list(cashflow_id='servicing',kind='COST',period_end=period,amount=cost)));list(actions=list(list(action_id='plan',currency='EUR',uptake_probability=.25,accepted_scenarios=list(scenario('accept',80,10)),declined_scenarios=list(scenario('decline',20,0)),offer_cost=2,support_status='SYNTHETIC_ASSUMPTION',assumption_reference='analytic-hand-case')),discount_factors=.9,ead=100,currency='EUR',period_end_dates=period)}
a<-c_recovery();v<-do.call(expected_collections_value,a)$value[[1]];stopifnot(v$expected_net_recovery==27.25,v$scenario_min==16,v$scenario_max==61,!v$causal_effect_identified)
a$ead<-0;stopifnot(is.null(do.call(expected_collections_value,a)$value[[1]]$expected_net_recovery_to_ead));a$actions[[1]]$uptake_probability<-0;stopifnot(do.call(expected_collections_value,a)$value[[1]]$expected_net_recovery==16)
a<-c_recovery();a$actions[[1]]$accepted_scenarios[[1]]$cashflows[[3]]<-a$actions[[1]]$accepted_scenarios[[1]]$cashflows[[1]];c_error('DATA_DUPLICATE',do.call(expected_collections_value,a))
for(fn in c('simulate_repayment_arrangement','expected_collections_value')){a<-if(fn=='simulate_repayment_arrangement')c_arrangement()else c_recovery();a$context<-list(currency='USD');c_error('TARGET_MISMATCH',do.call(get(fn),a))}
cat('collections native independent dated-history and ledger cases passed\n')
# Exact claim conservation with initial fees/interest, new fees and partial receipts.
a<-c_arrangement();a$contract$fees<-30;a$contract$accrued_interest<-20;a$candidate$new_fees<-c(5,0,5);a$candidate$period_interest_rates<-c(.01,.02,.03);a$candidate$receipt_fractions<-c(.5,.5,.5);v<-do.call(simulate_repayment_arrangement,a)$value$candidate;snapshot<-1050
for(row in v$schedule){closing<-row$closing_principal+row$unpaid_interest+row$unpaid_fees;c_near(closing,snapshot+row$interest_accrued+row$new_fees-row$received_payment);snapshot<-closing};c_near(v$remaining_claim,snapshot)
a<-c_case();a$states<-a$actions<-a$coverage<-list();h<-do.call(build_collections_episodes,a);stopifnot(length(h$value$episodes)==0,length(h$value$state_history)==0,length(build_cure_targets(h,30,30,a$evaluation_cutoff)$value)==0)
a<-c_action();a$actions<-list();stopifnot(length(do.call(build_collections_action_history,a)$value$rows)==0)
cat('collections empty histories and claim conservation passed\n')

# Date-only records on the action day cannot establish pre-action availability.
a<-c_action();a$features[[3]]<-a$features[[1]];a$features[[3]]$feature_record_id<-'same-day';a$features[[3]]$observed_at<-a$features[[3]]$known_at<-'2024-01-10';a$features[[3]]$value<-9000;stopifnot(do.call(build_collections_action_history,a)$value$rows[[1]]$preaction_features$income==2000)
a$features<-a$features[3];v<-do.call(build_collections_action_history,a)$value$rows[[1]];stopifnot(is.null(v$preaction_features$income),identical(v$missing_features,list('income')),!v$descriptive_eligible)
cat('strict pre-index feature chronology passed\n')
